    "category": "dependency_slow",
    "service": "queue-master",
    "summary": "Queue-master repeatedly fails to launch worker containers because the Docker socket is missing, causing its own processing to slow/stall."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "Docker socket /var/run/docker.sock is missing or unavailable, causing AFUNIXSocketException when queue-master attempts to communicate with the Docker daemon.",
      "status": "confirmed",
      "cites": [
        "queue-master-L0000c"
      ]
    },
    {
      "claim": "Due to the socket error, queue-master cannot launch or remove worker containers, leaving its worker pool depleted and slowing its processing of queued work (dependency_slow).",
      "status": "confirmed",
      "cites": [
        "queue-master-L0000c",
        "queue-master-L00240"
      ]
    },
    {
      "claim": "The depleted worker pool creates a backlog of pending tasks, increasing latency and causing timeouts for user requests that flow through gateway → orders → inventory/payments, which is observed as user‑visible errors or latency.",
      "status": "uncertain",
      "cites": [
        "queue-master-L00240"
      ]
    }
  ],
  "alternatives": [
    {
      "category": "process_crash",
      "service": "queue-master",
      "why_less_likely": "Queue-master continues to log INFO messages (e.g., I/O exception lines) and ERROR messages throughout the incident window, showing the process remained alive.",
